Then compute newLead, newLag, newRunCount, assign to outputs, update prev from newLead/newLag. That avoids mixing.

Let's design robust ST:

FUNCTION_BLOCK FB
VAR_INPUT
    demand : INT;
    runHours : ARRAY[1..5] OF LINT;
    rotated : BOOL;
END_VAR
VAR_OUTPUT
    leadPump : INT;
    lagPump : INT;
    runningCount : INT;
END_VAR
VAR
    prevLead : INT := 0;
    prevLag : INT := 0;
    prevRunCount : INT := 0;
    prevClipped : INT := 0;
    // local
    clipped : INT;
    newLead : INT;
    newLag : INT;
    newRunningCount : INT;
    minP : INT;
    minH : LINT;
    i : INT;
END_VAR

Implementation steps in body:
// 1. clip
IF demand < 0 THEN
    clipped := 0;
ELSIF demand > 5 THEN
    clipped := 5;
ELSE
    clipped := demand;
END_IF;

newRunningCount := clipped;
runningCount := newRunningCount; // maybe assign here or at end

// 2. if clipped <= 0:
IF clipped <= 0 THEN
    newLead := 0;
    newLag := 0;
ELSE
    // demand positive
    // lead selection
    IF prevLead = 0 THEN
        // initial select min
        // compute minPump all
        minP := 1;
        minH := runHours[1];
        FOR i := 2 TO 5 DO
            IF (runHours[i] < minH) OR ((runHours[i] = minH) AND (i < minP)) THEN
                minP := i;
                minH := runHours[i];
            END_IF;
        END_FOR;
        newLead := minP;
    ELSE
        // prevLead valid 1..5
        IF rotated THEN
            // compute minPump all
            minP := 1;
            minH := runHours[1];
            FOR i := 2 TO 5 DO
                IF (runHours[i] < minH) OR ((runHours[i] = minH) AND (i < minP)) THEN
                    minP := i;
                    minH := runHours[i];
                END_IF;
            END_FOR;
            // check hysteresis
            IF (runHours[prevLead] - runHours[minP] > 50) THEN
                newLead := minP;
            ELSE
                newLead := prevLead;
            END_IF;
        ELSE
            newLead := prevLead;
        END_IF;
    END_IF;

    // lag selection
    IF clipped < 2 THEN
        newLag := 0;
    ELSE
        // demand >=2
        // check selection moments
        IF (newLead <> prevLead) OR (clipped > prevClipped) THEN
            // select min excluding newLead
            minP := 0;
            minH := 0;
            FOR i := 1 TO 5 DO
                IF i <> newLead THEN
                    IF minP = 0 THEN
                        minP := i;
                        minH := runHours[i];
                    ELSE
                        IF (runHours[i] < minH) OR ((runHours[i] = minH) AND (i < minP)) THEN
                            minP := i;
                            minH := runHours[i];
                        END_IF;
                    END_IF;
                END_IF;
            END_FOR;
            newLag := minP;
        ELSE
            newLag := prevLag;
        END_IF;
    END_IF;
END_IF;

// assign outputs
leadPump := newLead;
lagPump := newLag;
runningCount := newRunningCount;

// update prev state
prevLead := newLead;
prevLag := newLag;
prevRunCount := newRunningCount;
prevClipped := clipped;

